"""Small math helpers."""


def add(a, b):
    """Return a plus b."""
    return a + b


def subtract(a, b):
    """Return a minus b."""
    return a - b


def median(lst):
    """Return the median of a list of numbers."""
    if not lst:
        raise ValueError("The list is empty.")

    lst.sort()
    n = len(lst)
    mid = n // 2

    if n % 2 == 0:
        # If even, return the average of the two middle numbers
        return (lst[mid - 1] + lst[mid]) / 2
    else:
        # If odd, return the middle number
        return lst[mid]
